message.content:
{
  "description": "The creature is shown in right-facing side profile standing on a light ground against a plain background. It has the overall body, head, legs and shaggy coat of a goat but carries a large domed turtle-like shell on its mid-back. The coat is long and shaggy, dark brown on the neck, back, sides and legs with a paler creamy-white underbelly and chest. The head is goat-like with a beard, the back is covered by the patterned carapace, and the rear ends in a short tufted tail. All four legs end in cloven hooves.",
  "parts": [
    {
      "part": "head",
      "looks_like": "goat-like head covered in brown shaggy fur with a slightly elongated muzzle, dark nostrils, dark eyes with light irises, and a small tufted beard under the chin",
      "where": "at the front end of the body on top of the long neck, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "two thick, ridged, curved horns, dark gray-brown with visible growth rings, tapering to points and curving backward and slightly outward",
      "where": "on top of the head behind the forehead, one on each side"
    },
    {
      "part": "ears",
      "looks_like": "two small, pointed, upright ears covered in brown fur with darker interiors",
      "where": "on the sides of the head just behind and below the horns"
    },
    {
      "part": "mane",
      "looks_like": "long, shaggy, wavy brown fur forming a thick ruff along the neck, chest, sides and hindquarters, lighter creamy-white on the belly and underside",
      "where": "covering the neck, chest, torso and upper legs, surrounding the shell on the back"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, straight, fur-covered legs, shaggy brown fur down to the hooves, with visible joints",
      "where": "under the torso, two forelegs at the front under the chest and two hind legs at the rear under the hips"
    },
    {
      "part": "feet",
      "looks_like": "cloven hooves, dark brown to black, split into two toes with blunt nails, with small dewclaws visible above",
      "where": "at the bottom tip of each of the four legs resting on the ground"
    },
    {
      "part": "tail",
      "looks_like": "short, shaggy tuft of brown fur, slightly lighter at the tip, hanging down",
      "where": "at the rear end of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large domed carapace with a dark brown to black base color and yellow to golden-brown radiating patterns, divided into polygonal scutes with raised pyramidal centers",
      "where": "on the dorsal mid-back, sitting on top of the fur from behind the shoulders to above the hips"
    },
    {
      "part": "plates",
      "looks_like": "individual geometric scutes of the shell, each with concentric growth lines and a raised pointed center, outlined in thin light lines with dark and yellow patterning",
      "where": "forming the entire surface of the shell on the back"
    },
    {
      "part": "markings",
      "looks_like": "natural color pattern of dark shell with yellow markings and brown fur shading from dark brown on the back to pale cream on the belly",
      "where": "on the shell surface and across the fur of the torso"
    }
  ],
  "attached_objects": [],
  "animals": [
    "goat",
    "turtle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
